#!/usr/bin/env bash
# Acceptance checks for c0265. SEQUESTERED: never edit during execution.
# One `check "ACn: ..."` per Checked acceptance criterion, in the same order as the issue doc.
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)" # physical: tests/run strips the physical cwd
source "$(git -C "$HERE" rev-parse --show-toplevel)/z-nile/lib/ac.sh" # cds to the item's project home
# sequestered specs: here before `./zn done`, promoted to its project's tests/acceptance/c0265 after it
A="$HERE/acceptance"
[[ -d $A ]] || A="$PWD/tests/acceptance/c0265"

# Work outside `check` is limited to running a spec through `tests/run` (which AC_LIST=1 list mode refuses),
# `./zn members` and other cheap reads; everything else goes inside `check`.
check "AC1: the pure rules: a beat is the branch hb/<claim stamp> whose commit subject carries the epoch, replaced with the one lease rule (the sha this checkout last wrote, else the sha seen, else create-only) and never backwards; a takeover creates the taker's branch and deletes the old owner's with a lease; a rejected beat learns whether it lost the claim; a claim is stale only strictly past 900 s and a never-beaten claim is silent since it landed; a stamp is parked when a pull request names any item holding it; the clock, the takeover rule and the watch loop's stops are decided; a stale claim is lost only when the pull requests were read and none names it, parked when one does, and stays unknown when they could not be read; lost work is ordered first and longest silent first; and only long-unclaimed branches are listed for deletion, each with its lease" lune run tests/run -- "$A/heartbeat.spec.luau"
check "AC2: a claim, ready, new raft, any ./zn command in a claimed worktree (once an interval has passed, never in the main checkout) and beat each write the beat as a one-commit branch hb/<stamp> that changes no path (main gets only the claim, no file changes, ./zn busy stays silent), beat works from the main checkout, keeps another terminal's fresh beat of a claim it has not fetched, never beats from a protected (fenced) checkout and the explicit beat refuses there, refuses what nobody claims (done items included), and --watch refuses to run without a numeric bound" lune run tests/run -- "$A/beat.spec.luau"
check "AC3: lost and status say which claims are lost and list them first, tag parked and unconfirmed ones without calling them lost, a never-beaten claim and an unstarted readied raft are lost, a takeover that meets a restamped claim is refused, fold beats, a beat revives one, unreadable beats or pull requests, a malformed beat ref make nothing lost and refuse a takeover, a failed beat attempt is not retried inside the interval, the takeover is recorded in the claim commit's subject, the board's model carries each verdict (lost, parked, stale) with lost work first in its bucket (longest silent first) and the publish-rebuilt board too, a protected checkout reads no remote (the board carries no verdicts, status refuses before any fetch, lost says so), an entry for a claim that ended says so, a failed first beat does not fail the claim, a lost claim (an issue's or a raft's) is taken over with a fresh stamp (a bare beat from a checkout that does not hold the claim, a restarted loop, an adoption over a remembered stamp and the dispatcher's stamp-bound form never adopt the taker's claim; a lost readied raft is taken over by stop then ready; the takeover deletes the old owner's branch and creates its own in one push), a beat that races a takeover is rejected by its lease and the old owner learns it lost the claim, a create-only beat that races one deletes what it created, and the old claimant's carried move is refused and its worktree stops beating" lune run tests/run -- "$A/lost.spec.luau" "$A/edge.spec.luau"
check "AC4: a model step the dispatcher runs on a claimed item beats for it while the step works (not only before or after); the proof is pinned by hash, so a changed proof fails here" bash -c '[[ ! -d "$0/acceptance" ]] || { [[ $(git hash-object "$0/proofs/dispatch.spec.luau") == 6fd10bdfa0c73e43b857b62b3f1ab603db903ec4 ]] || { echo "proofs/dispatch.spec.luau changed since it was pinned" >&2; exit 1; }; lune run tests/run -- "$0/proofs/dispatch.spec.luau"; }' "$HERE"
check "AC5: (the proof is pinned by hash, so a changed proof fails here) a hung remote is bounded, beat --watch says a failed tick, keeps beating, ends before its bound and stops when its claim is restamped, and a long check beats while it runs" bash -c '[[ ! -d "$0/acceptance" ]] || { [[ $(git hash-object "$0/proofs/race.spec.luau") == 5ae722350d3d2bf820b4bc9b1ebaf9000c0fde09 ]] || { echo "proofs/race.spec.luau changed since it was pinned" >&2; exit 1; }; lune run tests/run -- "$0/proofs/race.spec.luau"; }' "$HERE"
check "AC6: the usage text, zz-rules, the skills and the README name the heartbeat: beat and lost commands, the loop under ./zn run --time 3600, the lost-first pick in z-design, z-raft and z-run, the takeover-branch sentence in z-design and z-run (--takeover in both, --adopt in z-run), lost work before rank in the README's Order section, the NTP sentence in SETUP.md and the zz-test never-beats line" bash -c '
  set -e
  g() { grep -qF -e "$1" "$2" || { echo "missing in $2: $1" >&2; exit 1; }; }
  R="$ZN_ROOT/z-nile"
  for c in "  beat <id>" "  lost " "--takeover"; do g "$c" "$R/engine/main.luau"; done
  for w in "refs/heads/hb/" "./zn beat" "./zn lost" "parked"; do g "$w" "$R/skills/zz-rules/SKILL.md"; done
  g "--takeover" "$R/skills/z-design/SKILL.md"; g "--takeover" "$R/skills/z-run/SKILL.md"; g "--adopt" "$R/skills/z-run/SKILL.md"
  for s in z-design z-raft z-run zz-execute; do g "./zn beat" "$R/skills/$s/SKILL.md"; g "--time 3600" "$R/skills/$s/SKILL.md"; done
  for s in z-design z-raft z-run; do g "./zn lost" "$R/skills/$s/SKILL.md"; done
  g "re-adopt" "$R/skills/z-run/SKILL.md"
  sed -n "/^### Order/,/^### /p" "$R/README.md" | grep -qF "./zn lost" || { echo "README Order does not name ./zn lost" >&2; exit 1; }
  grep -qF "NTP" "$ZN_ROOT/SETUP.md" || { echo "SETUP.md does not name NTP" >&2; exit 1; }
  grep -qF "never beats" "$R/skills/zz-test/SKILL.md" || { echo "zz-test has no never-beats line" >&2; exit 1; }
  grep -qE "^\| .* \| c0265 \| exists \|" "$R/README.md" || { echo "README roadmap has no c0265 exists row" >&2; exit 1; }
'

check "AC7: taking over a lost claim discards the old worker's worktree and recovers its work: the old worktree stays at its path marked discarded with its branch renamed, a numbered copy <name>-<n> (smallest free number) on the original branch name continues the pushed branch (the PR head is untouched), the dirty files and unpushed commits are listed and kept, a plain worktree lookup finds the copy, a live, parked, unreadable or claim-less worktree and a fresh copy cannot be taken over this way, and the old process is told it was discarded by every command, the beat included" lune run tests/run -- "$A/discard.spec.luau"

finish
